`timescale 1ns / 1ps
//
// Self-checking testbench for src/lab3 (5-stage RV32I pipeline + simulated UART).
//
//  * runs the sort benchmark in core/rom.mem to completion
//  * captures every character written to the simulated UART (0x10000000)
//  * compares the captured text against what lab3_ref/src/sort.c must print
//  * checks the write-back trace (PC_WB / inst_WB / rd_WB / RegWrite_WB / wt_data_WB)
//    of the first 12 committed pipeline slots against a hand-derived reference
//
module tb_lab3;

    reg clk, rst;

    wire [31:0] wb_pc, wb_inst, mem_addr, mem_data;
    wire [7:0]  sim_uart_char_out;
    wire        sim_uart_char_valid;

    RV32core core(
        .debug_en(1'b0),
        .debug_step(1'b0),
        .debug_addr(7'b0),
        .debug_data(),
        .clk(clk),
        .rst(rst),
        .wb_pc(wb_pc),
        .wb_inst(wb_inst),
        .mem_addr(mem_addr),
        .mem_data(mem_data),
        .interrupter(1'b0),
        .sim_uart_char_out(sim_uart_char_out),
        .sim_uart_char_valid(sim_uart_char_valid)
    );

    // ------------------------------------------------------------------
    // clock / reset
    // ------------------------------------------------------------------
    initial begin
        clk = 1'b0;
        rst = 1'b1;
        #25 rst = 1'b0;
    end
    always #5 clk = ~clk;

    // ------------------------------------------------------------------
    // UART capture
    // ------------------------------------------------------------------
    localparam MAXCHAR = 4096;
    reg [7:0] uart_buf [0:MAXCHAR-1];
    integer   uart_n;

    // expected program output, derived from lab3_ref/src/sort.c
    reg [7:0] exp_buf [0:MAXCHAR-1];
    integer   exp_n;

    // ------------------------------------------------------------------
    // WB trace capture
    // ------------------------------------------------------------------
    localparam MAXWB = 32;
    reg        wb_started;
    integer    wb_n;
    reg [31:0] tr_pc   [0:MAXWB-1];
    reg [31:0] tr_inst [0:MAXWB-1];
    reg [4:0]  tr_rd   [0:MAXWB-1];
    reg        tr_rw   [0:MAXWB-1];
    reg [31:0] tr_wd   [0:MAXWB-1];

    // reference WB trace for the first 12 committed slots
    localparam NREF = 12;
    reg [31:0] ref_pc   [0:NREF-1];
    reg [31:0] ref_inst [0:NREF-1];
    reg [4:0]  ref_rd   [0:NREF-1];
    reg        ref_rw   [0:NREF-1];
    reg [31:0] ref_wd   [0:NREF-1];
    reg [8*40:1] ref_txt [0:NREF-1];

    integer cyc;
    integer idle_cnt;
    reg [31:0] last_wb_pc;

    integer i;
    integer errors;
    integer uart_errors;
    integer wb_errors;

    // ------------------------------------------------------------------
    // helper: append a string to the expected buffer
    // ------------------------------------------------------------------
    task put_exp;
        input [8*64:1] str;
        integer k;
        reg [7:0] ch;
        begin
            // strings are right justified in the reg vector; skip leading NULs
            for (k = 64; k >= 1; k = k - 1) begin
                ch = str[k*8 -: 8];
                if (ch != 8'h00) begin
                    exp_buf[exp_n] = ch;
                    exp_n = exp_n + 1;
                end
            end
        end
    endtask

    task put_num;   // decimal, followed by a space (mimics puti + puts(" "))
        input integer v;
        integer d, started_d, k;
        begin
            started_d = 0;
            d = 10000;
            if (v == 0) begin
                exp_buf[exp_n] = "0"; exp_n = exp_n + 1;
            end else begin
                for (k = 4; k >= 0; k = k - 1) begin
                    if (((v / d) % 10) != 0 || started_d) begin
                        exp_buf[exp_n] = 8'h30 + ((v / d) % 10);
                        exp_n = exp_n + 1;
                        started_d = 1;
                    end
                    d = d / 10;
                end
            end
            exp_buf[exp_n] = " "; exp_n = exp_n + 1;
        end
    endtask

    integer a_init [0:19];
    integer b_init [0:19];

    initial begin
        uart_n     = 0;
        exp_n      = 0;
        wb_started = 1'b0;
        wb_n       = 0;
        cyc        = 0;
        idle_cnt   = 0;
        last_wb_pc = 32'hffffffff;
        errors     = 0;

        // ---- build the expected UART text ----------------------------
        a_init[0]=2;  a_init[1]=12; a_init[2]=14; a_init[3]=6;  a_init[4]=13;
        a_init[5]=15; a_init[6]=16; a_init[7]=10; a_init[8]=0;  a_init[9]=18;
        a_init[10]=11;a_init[11]=19;a_init[12]=9; a_init[13]=1; a_init[14]=7;
        a_init[15]=5; a_init[16]=4; a_init[17]=3; a_init[18]=8; a_init[19]=17;

        b_init[0]=7;  b_init[1]=3;  b_init[2]=0;  b_init[3]=13; b_init[4]=2;
        b_init[5]=6;  b_init[6]=5;  b_init[7]=9;  b_init[8]=10; b_init[9]=4;
        b_init[10]=18;b_init[11]=11;b_init[12]=14;b_init[13]=16;b_init[14]=1;
        b_init[15]=17;b_init[16]=19;b_init[17]=15;b_init[18]=8; b_init[19]=12;

        for (i = 0; i < 20; i = i + 1) put_num(a_init[i]);     // display(a)
        exp_buf[exp_n] = 8'h0a; exp_n = exp_n + 1;
        for (i = 0; i < 20; i = i + 1) put_num(i);             // bubble_sort -> ascending
        exp_buf[exp_n] = 8'h0a; exp_n = exp_n + 1;
        for (i = 0; i < 20; i = i + 1) put_num(b_init[i]);     // display(b)
        exp_buf[exp_n] = 8'h0a; exp_n = exp_n + 1;
        for (i = 0; i < 20; i = i + 1) put_num(19 - i);        // select_sort -> descending
        exp_buf[exp_n] = 8'h0a; exp_n = exp_n + 1;

        // ---- reference WB trace --------------------------------------
        // PC values are ROM byte offsets (the linked program at 0x80000000 is
        // fetched from ROM_D through PC[9:2]).
        ref_pc[0]=32'h00000000; ref_inst[0]=32'h00000413; ref_rd[0]=5'd8;  ref_rw[0]=1'b1; ref_wd[0]=32'h00000000; ref_txt[0]="addi s0,zero,0";
        ref_pc[1]=32'h00000004; ref_inst[1]=32'h00009117; ref_rd[1]=5'd2;  ref_rw[1]=1'b1; ref_wd[1]=32'h00009004; ref_txt[1]="auipc sp,0x9";
        ref_pc[2]=32'h00000008; ref_inst[2]=32'hffc10113; ref_rd[2]=5'd2;  ref_rw[2]=1'b1; ref_wd[2]=32'h00009000; ref_txt[2]="addi sp,sp,-4";
        ref_pc[3]=32'h0000000c; ref_inst[3]=32'h1fc000ef; ref_rd[3]=5'd1;  ref_rw[3]=1'b1; ref_wd[3]=32'h00000010; ref_txt[3]="jal ra,_trm_init";
        ref_pc[4]=32'h0000000c; ref_inst[4]=32'h00000013; ref_rd[4]=5'd0;  ref_rw[4]=1'b1; ref_wd[4]=32'h00000000; ref_txt[4]="(branch bubble/NOP)";
        ref_pc[5]=32'h00000208; ref_inst[5]=32'h80000537; ref_rd[5]=5'd10; ref_rw[5]=1'b1; ref_wd[5]=32'h80000000; ref_txt[5]="lui a0,0x80000";
        ref_pc[6]=32'h0000020c; ref_inst[6]=32'hff010113; ref_rd[6]=5'd2;  ref_rw[6]=1'b1; ref_wd[6]=32'h00008ff0; ref_txt[6]="addi sp,sp,-16";
        ref_pc[7]=32'h00000210; ref_inst[7]=32'h41050513; ref_rd[7]=5'd10; ref_rw[7]=1'b1; ref_wd[7]=32'h80000410; ref_txt[7]="addi a0,a0,1040";
        ref_pc[8]=32'h00000214; ref_inst[8]=32'h00112623; ref_rd[8]=5'd12; ref_rw[8]=1'b0; ref_wd[8]=32'h00008ffc; ref_txt[8]="sw ra,12(sp)";
        ref_pc[9]=32'h00000218; ref_inst[9]=32'hf25ff0ef; ref_rd[9]=5'd1;  ref_rw[9]=1'b1; ref_wd[9]=32'h0000021c; ref_txt[9]="jal ra,main";
        ref_pc[10]=32'h00000218;ref_inst[10]=32'h00000013;ref_rd[10]=5'd0; ref_rw[10]=1'b1;ref_wd[10]=32'h00000000;ref_txt[10]="(branch bubble/NOP)";
        ref_pc[11]=32'h0000013c;ref_inst[11]=32'hff010113;ref_rd[11]=5'd2; ref_rw[11]=1'b1;ref_wd[11]=32'h00008fe0;ref_txt[11]="addi sp,sp,-16 (main)";
    end

    // ------------------------------------------------------------------
    // sampling
    // ------------------------------------------------------------------
    always @(negedge clk) if (!rst) begin
        cyc = cyc + 1;

        // ---- UART ----
        if (sim_uart_char_valid) begin
            if (uart_n < MAXCHAR) begin
                uart_buf[uart_n] = sim_uart_char_out;
                uart_n = uart_n + 1;
            end
        end

        // ---- WB trace ----
        if (!wb_started && (core.PC_WB == 32'h00000000) && (core.inst_WB == 32'h00000413))
            wb_started = 1'b1;
        if (wb_started && (wb_n < MAXWB)) begin
            tr_pc[wb_n]   = core.PC_WB;
            tr_inst[wb_n] = core.inst_WB;
            tr_rd[wb_n]   = core.rd_WB;
            tr_rw[wb_n]   = core.RegWrite_WB;
            tr_wd[wb_n]   = core.wt_data_WB;
            wb_n = wb_n + 1;
        end

        // ---- completion detection: _trm_init's endless loop at 0x21c ----
        if (core.PC_WB == 32'h0000021c) idle_cnt = idle_cnt + 1;
        else idle_cnt = 0;
    end

    // ------------------------------------------------------------------
    // main
    // ------------------------------------------------------------------
    localparam MAXCYC = 400000;

    initial begin
        wait (rst == 1'b0);
        while (cyc < MAXCYC && idle_cnt < 40) @(negedge clk);
        #1;
        report;
        $finish;
    end

    task report;
        integer k;
        reg [7:0] c;
        begin
            uart_errors = 0;
            wb_errors   = 0;

            $display("");
            $display("==========================================================");
            $display(" lab3 self-checking testbench");
            $display("==========================================================");
            $display(" cycles simulated : %0d (limit %0d)", cyc, MAXCYC);
            if (idle_cnt >= 40)
                $display(" program reached the _trm_init idle loop @ PC 0x0000021c : YES");
            else
                $display(" program reached the _trm_init idle loop @ PC 0x0000021c : NO  <-- FAIL");

            // ---------------- WB trace ----------------
            $display("");
            $display("---- write-back trace, first %0d committed slots ----", NREF);
            $display(" #   PC_WB      inst_WB    rd  RegWrite wt_data_WB   expected                                     result");
            for (k = 0; k < NREF; k = k + 1) begin
                if (k >= wb_n) begin
                    $display("%2d   <missing>                                                                                FAIL", k);
                    wb_errors = wb_errors + 1;
                end else if (tr_pc[k] === ref_pc[k] && tr_inst[k] === ref_inst[k] &&
                             tr_rd[k] === ref_rd[k] && tr_rw[k] === ref_rw[k] &&
                             tr_wd[k] === ref_wd[k]) begin
                    $display("%2d   0x%08h 0x%08h x%0d%s %b        0x%08h   %0s%s PASS",
                             k, tr_pc[k], tr_inst[k], tr_rd[k], (tr_rd[k]>9)?"":" ", tr_rw[k], tr_wd[k],
                             ref_txt[k], "  ");
                end else begin
                    wb_errors = wb_errors + 1;
                    $display("%2d   got 0x%08h 0x%08h rd=x%0d rw=%b wd=0x%08h", k, tr_pc[k], tr_inst[k], tr_rd[k], tr_rw[k], tr_wd[k]);
                    $display("     exp 0x%08h 0x%08h rd=x%0d rw=%b wd=0x%08h  (%0s)  FAIL",
                             ref_pc[k], ref_inst[k], ref_rd[k], ref_rw[k], ref_wd[k], ref_txt[k]);
                end
            end

            // ---------------- UART ----------------
            $display("");
            $display("---- captured UART output (%0d chars) ----", uart_n);
            $write("[");
            for (k = 0; k < uart_n; k = k + 1) begin
                c = uart_buf[k];
                if (c == 8'h0a) $write("\\n");
                else $write("%c", c);
            end
            $display("]");
            $display("---- expected UART output (%0d chars) ----", exp_n);
            $write("[");
            for (k = 0; k < exp_n; k = k + 1) begin
                c = exp_buf[k];
                if (c == 8'h0a) $write("\\n");
                else $write("%c", c);
            end
            $display("]");

            if (uart_n != exp_n) begin
                uart_errors = uart_errors + 1;
                $display(" UART length mismatch: expected %0d, got %0d", exp_n, uart_n);
            end
            for (k = 0; k < ((uart_n < exp_n) ? uart_n : exp_n); k = k + 1) begin
                if (uart_buf[k] !== exp_buf[k]) begin
                    if (uart_errors < 10)
                        $display(" UART mismatch at char %0d: expected 0x%02h '%c', got 0x%02h '%c'",
                                 k, exp_buf[k], exp_buf[k], uart_buf[k], uart_buf[k]);
                    uart_errors = uart_errors + 1;
                end
            end

            // ---------------- summary ----------------
            errors = wb_errors + uart_errors + ((idle_cnt >= 40) ? 0 : 1);
            $display("");
            $display("---------------- summary ----------------");
            $display(" check                         expected                    actual                      result");
            $display(" program terminates            idle loop @0x21c            %0s                        %0s",
                     (idle_cnt >= 40) ? "idle loop @0x21c        " : "still running           ",
                     (idle_cnt >= 40) ? "PASS" : "FAIL");
            $display(" WB trace (first %0d slots)      matches reference           %0d mismatch(es)            %0s",
                     NREF, wb_errors, (wb_errors == 0) ? "PASS" : "FAIL");
            $display(" UART char count               %0d                         %0d                         %0s",
                     exp_n, uart_n, (exp_n == uart_n) ? "PASS" : "FAIL");
            $display(" UART text                     sort.c reference output     %0d mismatch(es)            %0s",
                     uart_errors, (uart_errors == 0) ? "PASS" : "FAIL");
            $display("");
            if (errors == 0) $display(" OVERALL: PASS");
            else             $display(" OVERALL: FAIL (%0d problem(s))", errors);
            $display("==========================================================");
        end
    endtask

endmodule

