`timescale 1ns / 1ps
//
// Directed micro-test for src/lab3.
// Runs the program produced by gen_directed.py and checks the final register
// file contents plus hazard/forwarding path coverage.
//
module tb_directed;

    reg clk, rst;

    RV32core core(
        .debug_en(1'b0),
        .debug_step(1'b0),
        .debug_addr(7'b0),
        .debug_data(),
        .clk(clk),
        .rst(rst),
        .wb_pc(),
        .wb_inst(),
        .mem_addr(),
        .mem_data(),
        .interrupter(1'b0),
        .sim_uart_char_out(),
        .sim_uart_char_valid()
    );

    initial begin
        clk = 1'b0;
        rst = 1'b1;
        #25 rst = 1'b0;
    end
    always #5 clk = ~clk;

    reg [31:0] exp_reg [0:31];
    reg [31:0] halt_pc_mem [0:0];
    reg [31:0] halt_pc;

    integer cyc, idle, i, errors;
    integer n_stall, n_fwd_ls, n_fwdA, n_fwdB;

    initial begin
        $readmemh("expected_regs.mem", exp_reg);
        $readmemh("halt_pc.mem", halt_pc_mem);
        halt_pc = halt_pc_mem[0];
        cyc = 0; idle = 0; errors = 0;
        n_stall = 0; n_fwd_ls = 0; n_fwdA = 0; n_fwdB = 0;
    end

    always @(negedge clk) if (!rst) begin
        cyc = cyc + 1;
        if (core.reg_FD_stall)            n_stall  = n_stall + 1;
        if (core.forward_ctrl_ls)         n_fwd_ls = n_fwd_ls + 1;
        if (core.forward_ctrl_A != 2'b00) n_fwdA   = n_fwdA + 1;
        if (core.forward_ctrl_B != 2'b00) n_fwdB   = n_fwdB + 1;
        if (core.PC_WB == halt_pc) idle = idle + 1; else idle = 0;
    end

    initial begin
        wait (rst == 1'b0);
        while (cyc < 5000 && idle < 20) @(negedge clk);
        #1;
        $display("");
        $display("==========================================================");
        $display(" lab3 directed micro-test (ISA + hazard coverage)");
        $display("==========================================================");
        $display(" cycles: %0d   halt PC: 0x%08h   reached: %0s",
                 cyc, halt_pc, (idle >= 20) ? "YES" : "NO");
        if (idle < 20) errors = errors + 1;

        $display("");
        $display(" reg   expected     actual      result");
        for (i = 0; i < 32; i = i + 1) begin
            if (^exp_reg[i] === 1'bx) begin
                // don't care
            end else begin
                if (regval(i) === exp_reg[i])
                    $display(" x%0d%s  0x%08h  0x%08h  PASS", i, (i > 9) ? " " : "  ",
                             exp_reg[i], regval(i));
                else begin
                    $display(" x%0d%s  0x%08h  0x%08h  FAIL", i, (i > 9) ? " " : "  ",
                             exp_reg[i], regval(i));
                    errors = errors + 1;
                end
            end
        end

        $display("");
        $display(" coverage: reg_FD_stall=%0d  forward_ctrl_ls=%0d  forwardA=%0d  forwardB=%0d",
                 n_stall, n_fwd_ls, n_fwdA, n_fwdB);
        if (n_stall  == 0) begin $display(" NO load-use stall exercised -- FAIL");        errors = errors + 1; end
        if (n_fwd_ls == 0) begin $display(" NO load->store forwarding exercised -- FAIL"); errors = errors + 1; end

        $display("");
        if (errors == 0) $display(" OVERALL: PASS");
        else             $display(" OVERALL: FAIL (%0d problem(s))", errors);
        $display("==========================================================");
        $finish;
    end

    function [31:0] regval;
        input integer n;
        begin
            regval = (n == 0) ? 32'b0 : core.register.register[n];
        end
    endfunction

endmodule
